  "Sí": { de: "Ja", en: "Yes" },
  "Aún no ha recibido ninguna newsletter.": { de: "Hat noch keinen Newsletter erhalten.", en: "Hasn't received any newsletter yet." },
  "Privacidad: «Sus datos» descarga todo lo que guardas de ella. Si te pide borrarlos, usa «Borrar definitivamente».": { de: "Datenschutz: „Ihre Daten“ lädt alles herunter, was du über sie speicherst. Wenn sie die Löschung verlangt, nutze „Endgültig löschen“.", en: "Privacy: “Her data” downloads everything you keep about her. If she asks for it to be deleted, use “Delete permanently”." },
  "Reenviar confirmación": { de: "Bestätigung erneut senden", en: "Resend confirmation" },
  "Dar de baja": { de: "Abmelden", en: "Unsubscribe" },
  "Borrar definitivamente": { de: "Endgültig löschen", en: "Delete permanently" },
  "ella, con el enlace de baja": { de: "sie selbst, über den Abmeldelink", en: "she did, with the unsubscribe link" },
  "ella, con la baja en un clic del buzón": { de: "sie selbst, mit der Ein-Klick-Abmeldung im Postfach", en: "she did, with one-click unsubscribe in her inbox" },
