  "Para": { de: "Für", en: "For" },
  "¡Feliz cumpleaños! Te regalo tu lectura.": { de: "Alles Gute zum Geburtstag! Ich schenke dir deine Lesung.", en: "Happy birthday! Your reading is my gift to you." },
